INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37711, 'Isaiah 48:15', 'Isaiah', 48, 15, 'زه هغه ذات یم چې کورش ته مې اواز وکړ او ما راوغوښت هغه هغه دنده چې ما وسپارله هغه ته نو بری به یې شي په برخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_15.mp3', '', 1761754199, 1761754199),
(37712, 'Isaiah 48:16', 'Isaiah', 48, 16, 'اوس نژدې راشئ او څه چې وایم ورته غوږ ونیسئ ما له پیله په ښکاره خبرې کړې او له شروع نه مې لاس درلود په ټولو پېښو کې» اوس زه څښتن تعالی د خپل روح سره رالېږلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_16.mp3', '', 1761754199, 1761754199),
(37713, 'Isaiah 48:17', 'Isaiah', 48, 17, 'سپېڅلی خدای د اسراییلو هغه څښتن چې دی ژغورونکی ستاسو داسې وایي: «زه څښتن خدای یم ستاسو زه هغه ذات یمه چې غواړم درکړم تاسو ته تعلیم چې وي په ګټه ستاسو او درته ښایم هغه لاره چې پرې لاړ شئ تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_17.mp3', '', 1761754199, 1761754199),
(37714, 'Isaiah 48:18', 'Isaiah', 48, 18, 'کاشکې مو پام کړی وای زما حکمونو ته نو بیا به د سیند په شان جاري وای سوله ستاسو او بری به راروان وای ستاسو خواته په شان د بحیرې د څپو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_18.mp3', '', 1761754199, 1761754199),
(37715, 'Isaiah 48:19', 'Isaiah', 48, 19, 'لکه د شګو په شان به وای بې شمېره اولاده ستاسو او پرېښودلئ مې نه چې تاسو خپله او یا نوم ستاسو له منځه لاړ شي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_19.mp3', '', 1761754199, 1761754199),
(37716, 'Isaiah 48:20', 'Isaiah', 48, 20, 'وځئ بابل نه او وتښتئ! ټوله نړۍ کې کړئ اعلان دا زېری د خوشحالۍ په چیغو او ووایئ: «څښتن وژغوره خپل خدمتګار یعقوب!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_20.mp3', '', 1761754199, 1761754199),
(37717, 'Isaiah 48:21', 'Isaiah', 48, 21, 'په وچه دښته کې چې کله روان کړی ؤ څښتن خپل قوم هغوی یې پرېنښودل چې تږي شي څښتن د ګټ څخه جارې کړلې اوبه هغوی ته هغه سوری کړلو ګټ او وبهېدلې اوبه ورڅخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_21.mp3', '', 1761754199, 1761754199),
(37718, 'Isaiah 48:22', 'Isaiah', 48, 22, 'څښتن وایي: «سوله نشته بد عملو ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah48_verse_22.mp3', '', 1761754199, 1761754199),
(37719, 'Habakkuk 2:1', 'Habakkuk', 2, 1, 'زه به خپل د څارنې برج ته وخېژم او انتظار به وباسم، ترڅو وګورم چې څښتن ماته څه وایي او زما شکایت ته څه ځواب ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_1.mp3', '', 1761754199, 1761754199),
(37720, 'Habakkuk 2:2', 'Habakkuk', 2, 2, 'څښتن ماته دا ځواب راکړ: «څه چې زه درته په رویا کې ښایم هغه په روښانه توګه په لوحو باندې ولیکه، ترڅو هغه په اسانۍ سره ولوستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_2.mp3', '', 1761754199, 1761754199),
(37721, 'Habakkuk 2:3', 'Habakkuk', 2, 3, 'ځکه چې د هغې د عملي کېدلو وخت لا نه دی رارسېدلی. خو هغه وخت به زر راشي او هغه څه چې زه یې په رویا کې درته ښایم هغه به رښتیا شي. که څه هم هغه وخت ورو ورو راځي، خو هغه ته انتظار کوه. خامخا به داسې کیږي او په هغې کې کوم ځنډ نه رامنځته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_3.mp3', '', 1761754199, 1761754199),
(37722, 'Habakkuk 2:4', 'Habakkuk', 2, 4, 'ګورئ، هغه پیغام دا دی چې مغرور خلک به ژوندي نه پاتې کیږي، خو نېکان به د خپل ایمان په وسیله ژوند کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_4.mp3', '', 1761754199, 1761754199),
(37723, 'Habakkuk 2:5', 'Habakkuk', 2, 5, 'مال او دولت یو غولوونکی شی دی. مغروره خلک تل نا‌ارامه وي او د هغوی حرص لکه د قبر او مرګ په شان دی چې هېڅکله نه مړیږي، نو ځکه هغوی د خپلو ځانونو دپاره قومونه رانیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_5.mp3', '', 1761754199, 1761754199),
(37724, 'Habakkuk 2:6', 'Habakkuk', 2, 6, 'اسیران شوي خلک به هغو خلکو ته چې دوی یې نیولي دي، پېغور ورکوي او په هغوی باندې به ملنډې وهي. هغوی به وایي: «افسوس ستاسو په حال! تاسو ته به خدای سزا درکړي، ځکه چې تاسو هغه څه اخلئ چې ستاسو نه دي، ترڅو پورې به تاسو خپل ځانونه په هغو شیانو باندې شتمن کوئ چې خپل پوروړي مجبوروئ چې د خپل پور نه زیات شیان درکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_6.mp3', '', 1761754199, 1761754199),
(37725, 'Habakkuk 2:7', 'Habakkuk', 2, 7, 'نو د کومو خلکو نه چې تاسو کوم شیان اخیستې دي، هغوی به ناڅاپه ستاسو په وړاندې راپورته شي او ستاسو نه به د هغو نه زیات واخلي. هغوی به راشي او تاسو به له وېرې ولړزوي. هغوی به تاسو لوټ کړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_7.mp3', '', 1761754199, 1761754199),
(37726, 'Habakkuk 2:8', 'Habakkuk', 2, 8, 'تاسو د ډېرو قومونو خلک لوټ کړي دي، خو اوس چې څوک پاتې دي، هغوی به تاسو لوټ کړي، ځکه چې تاسو قتلونه کړي دي او د نړۍ او د هغې د ښارونو د خلکو سره مو ظلم زیاتی کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_8.mp3', '', 1761754199, 1761754199),
(37727, 'Habakkuk 2:9', 'Habakkuk', 2, 9, 'افسوس ستاسو په حال، ځکه چې تاسو چې په ظلم باندې کوم شیان اخیستي دي، په هغو باندې مو خپله کورنۍ شتمنه کړې ده او کوښښ مو کړی چې خپل کورونه د زیان او خطر نه په امن کې وساتئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_9.mp3', '', 1761754199, 1761754199),
(37728, 'Habakkuk 2:10', 'Habakkuk', 2, 10, 'خو ستاسې دسیسې ستاسو د رسوایۍ سبب شوې دي او په دې کار سره تاسو د ډېرو قومونو په له منځه وړلو سره په خپل ځان باندې تباهي راوستې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_10.mp3', '', 1761754199, 1761754199),
(37729, 'Habakkuk 2:11', 'Habakkuk', 2, 11, 'حتی د دېوالونو تیږې هم ستاسو په خلاف چیغې وهي او ستاسو د کورونو د چتونو تیران هم ستاسو په خلاف چیغې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_11.mp3', '', 1761754199, 1761754199),
(37730, 'Habakkuk 2:12', 'Habakkuk', 2, 12, 'افسوس ستاسو په حال، ځکه چې تاسو د ښار بنیاد په بې‌انصافۍ باندې ایښی دی او هغه مو د وینې په تویولو باندې جوړ کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_12.mp3', '', 1761754199, 1761754199),
(37731, 'Habakkuk 2:13', 'Habakkuk', 2, 13, 'مطلق قادر څښتن داسې اراده کړې ده چې کوم قومونه چې تاسو نیولي دي، هغوی خپل ځانونه هسې په کارونو ستړي کړي وو او هغه ټول شیان چې هغوی جوړ کړي وو، هغه به وسوځي او په ایرو باندې به بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_13.mp3', '', 1761754199, 1761754199),
(37732, 'Habakkuk 2:14', 'Habakkuk', 2, 14, 'ځکه چې ځمکه به د څښتن د جلال د پېژندنې نه داسې ډکه شي لکه څنګه چې بحیرې د اوبو نه ډکې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_14.mp3', '', 1761754199, 1761754199),
(37733, 'Habakkuk 2:15', 'Habakkuk', 2, 15, 'افسوس ستاسو په حال، ځکه چې تاسو په خپلو ګاونډیو قومونو باندې د خپل قهر د جام شراب وڅښل او هغوی مو نشه کړل او بیا مو هغوی وشرمول د دې دپاره چې د هغوی لوڅ بدنونه وګورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_15.mp3', '', 1761754199, 1761754199),
(37734, 'Habakkuk 2:16', 'Habakkuk', 2, 16, 'د هغې په بدل کې به تاسو د عزت په ځای په شرمونو پټ شئ. تاسو خپله به هغه وڅښئ او ستاسو لوڅوالی به ښکاره شي. څښتن به په تاسو باندې د خپلې سزا پیاله وڅښي او ستاسو عزت به په شرم او رسوایۍ باندې بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_16.mp3', '', 1761754199, 1761754199),
(37735, 'Habakkuk 2:17', 'Habakkuk', 2, 17, 'تاسو د لبنان سره ظلم کړی دی، نو په تاسو باندې به هم ظلم وشي. تاسو د هغو حیوانات ووژل، اوس به حیوانات تاسو وېروي. دا کار به کیږي، ځکه چې تاسو قتلونه کړي دي او د نړۍ او د هغې د ښارونو د خلکو سره مو ظلم زیاتی کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_17.mp3', '', 1761754199, 1761754199),
(37736, 'Habakkuk 2:18', 'Habakkuk', 2, 18, 'یو بت څه ګټه لري چې انسان جوړ کړی دی یا یوه مجسمه چې د دروغو تعلیم ورکوي؟ دا د خپل جوړوونکي سره څه ښېګڼه کولای شي چې هغه ورباندې توکل کوي، که څه هم هغه خبرې نه شي کولای؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_18.mp3', '', 1761754199, 1761754199),
(37737, 'Habakkuk 2:19', 'Habakkuk', 2, 19, 'افسوس ستاسو په حال چې د لرګي یوې ټوټې ته وایئ: ‹راویښه شه!› یا یوې تیږې ته وایئ: ‹پاڅېږه!› ایا بت تاسو ته کوم شی ښودلی شي؟ که څه هم هغه په سپینو یا سرو زرو باندې پوښل شوی وي، خو په هغه کې ساه نشته.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_19.mp3', '', 1761754199, 1761754199),
(37738, 'Habakkuk 2:20', 'Habakkuk', 2, 20, 'خو څښتن په خپل سپېڅلي عبادتځای کې دی، نو د ځمکې په مخ ټول خلک دې د هغه په حضور کې خاموش وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk2_verse_20.mp3', '', 1761754199, 1761754199),
(37739, 'Genesis 28:1', 'Genesis', 28, 1, 'اسحاق یعقوب راوغوښت، هغه ته یې برکت ورکړ او حکم یې ورته وکړ: «د کنعانۍ انجلۍ سره واده ونه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_1.mp3', '', 1761754199, 1761754199),
(37740, 'Genesis 28:2', 'Genesis', 28, 2, 'همدا‌اوس بین‌النهرین ته د خپل نیکه بتوییل کور ته لاړ شه او هلته د خپل ماما لابان د لورګانو څخه خپل ځان ته ښځه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_2.mp3', '', 1761754199, 1761754199),
(37741, 'Genesis 28:3', 'Genesis', 28, 3, 'مطلق قادر خدای دې برکت درکړي او ډېر اولادونه دې درکړي، ترڅو ستا څخه ډېر قومونه پیدا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_3.mp3', '', 1761754199, 1761754199),
(37742, 'Genesis 28:4', 'Genesis', 28, 4, 'هغه دې تا او ستا اولادې ته د ابراهیم په شان برکت درکړي او د هغې ځمکې خاوند شې چې خدای ابراهیم ته ورکړې ده او ته په کې اوس د یو پردي په شان اوسېږې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_4.mp3', '', 1761754199, 1761754199),
(37743, 'Genesis 28:5', 'Genesis', 28, 5, 'نو اسحاق یعقوب ولېږه او هغه بین‌النهرین ته د بتوییل آرامي زوی د یعقوب او عیسو د مور ربکا ورور لابان ته ورغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_5.mp3', '', 1761754199, 1761754199),
(37744, 'Genesis 28:6', 'Genesis', 28, 6, 'عیسو پوه شو چې اسحاق یعقوب ته برکت ورکړ او هغه یې بین‌النهرین ته ولېږه چې په هغه ځای کې ځان ته ښځه وکړي. هغه په دې هم پوه شو چې کله اسحاق هغه ته برکت ورکاوه، هغه ته یې حکم وکړ چې د کنعانۍ انجلۍ سره به واده نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_6.mp3', '', 1761754199, 1761754199),
(37745, 'Genesis 28:7', 'Genesis', 28, 7, 'هغه خبر شو چې یعقوب د خپل مور او پلار اطاعت وکړ او بین‌النهرین ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_7.mp3', '', 1761754199, 1761754199),
(37746, 'Genesis 28:8', 'Genesis', 28, 8, 'عیسو په دې پوهېده چې د هغه پلار اسحاق کنعانۍ ښځې نه خوښوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_8.mp3', '', 1761754199, 1761754199),
(37747, 'Genesis 28:9', 'Genesis', 28, 9, 'نو هغه د ابراهیم زوی اسماعیل ته لاړ او سره له دې چې نورې ښځې یې هم درلودلې، د اسماعیل د لور محلت سره یې چې د نبایوت خور وه، واده وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_9.mp3', '', 1761754199, 1761754199),
(37748, 'Genesis 28:10', 'Genesis', 28, 10, 'یعقوب د بیرشبع څخه حران ته روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_10.mp3', '', 1761754199, 1761754199),
(37749, 'Genesis 28:11', 'Genesis', 28, 11, 'کله چې نوموړی یو ځای ته ورسېده، لمر پرېوتی ؤ. هغه د شپې هلته پاتې شو او یوه تیږه یې راواخیستله، د خپل سر لاندې یې کېښودله او په هغه ځای کې ویده شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_11.mp3', '', 1761754199, 1761754199),
(37750, 'Genesis 28:12', 'Genesis', 28, 12, 'هغه په خوب کې یوه زینه ولیدله چې په ځمکه باندې ولاړه وه او سر یې اسمان ته رسېده او د خدای فرښتې په هغې باندې ښکته او پورته تللې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_12.mp3', '', 1761754199, 1761754199),
(37751, 'Genesis 28:13', 'Genesis', 28, 13, 'څښتن د یعقوب په څنګ کې ولاړ ؤ او ویې ویل: «زه څښتن یم، ستا د نیکه ابراهیم خدای او د اسحاق خدای یم. دغه ځمکه چې ته ورباندې پروت یې، تا او ستا اولادې ته به یې ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_13.mp3', '', 1761754199, 1761754199),
(37752, 'Genesis 28:14', 'Genesis', 28, 14, 'ستا اولاده به د دښتې د شګو په شان زیاته کړم او تاسو به د خپل هېواد لمرپرېواته، لمرخاته، شمال او جنوب خواته خپاره شئ او د دنیا ټول قومونه به ستا او ستا د اولادې په وسیله برکت مومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_14.mp3', '', 1761754199, 1761754199),
(37753, 'Genesis 28:15', 'Genesis', 28, 15, 'زه به ستا سره مل یم او هر‌چېرته چې ځې، زه به تا ساتم او بېرته به دې دې وطن ته راولم. تر هغې پورې به زه تا پرېنږدم، ترڅو مې هغه ټول کارونه نه وي کړي چې ستا سره مې وعده کړې وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_15.mp3', '', 1761754199, 1761754199),
(37754, 'Genesis 28:16', 'Genesis', 28, 16, 'کله چې یعقوب له خوبه راویښ شو، ویې ویل: «څښتن په دې ځای کې دی، خو زه په دې پوه نه وم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_16.mp3', '', 1761754199, 1761754199),
(37755, 'Genesis 28:17', 'Genesis', 28, 17, 'هغه ووېرېده او ویې ویل: «دا څومره وېروونکی ځای دی. په رښتیا سره دا د خدای کور دی او دا د اسمان دروازه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_17.mp3', '', 1761754199, 1761754199),
(37756, 'Genesis 28:18', 'Genesis', 28, 18, 'سهار وختي یعقوب هغه تیږه چې هغه د خپل سر لاندې ایښې وه، راواخیستله او د یادګار په توګه یې ودروله او د هغې په سر یې د زیتونو تېل واچول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_18.mp3', '', 1761754199, 1761754199),
(37757, 'Genesis 28:19', 'Genesis', 28, 19, 'هغه دا ځای د بیت‌ییل په نوم یاد کړ. خو پخوا د هغه ښار نوم لوز ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_19.mp3', '', 1761754199, 1761754199),
(37758, 'Genesis 28:20', 'Genesis', 28, 20, 'بیا یعقوب نذر کېښود، ویې ویل: «که چېرې خدای زما سره مل وي او په دې سفر کې چې زه روان یم ما وساتي او ډوډۍ او کالي راته راکړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_20.mp3', '', 1761754199, 1761754199),
(37759, 'Genesis 28:21', 'Genesis', 28, 21, 'ترڅو په خیر سره بېرته د خپل پلار کور ته ورستون شم، نو بیا به ته زما خدای یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_21.mp3', '', 1761754199, 1761754199),
(37760, 'Genesis 28:22', 'Genesis', 28, 22, 'او دغه تیږه چې ما د یادګار په توګه ودرولې ده، هغه به د خدای کور شي او هرڅه چې ماته یې راکوې، د هغو لسمه برخه به تاته درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis28_verse_22.mp3', '', 1761754199, 1761754199),
(37761, 'Ezekiel 44:1', 'Ezekiel', 44, 1, 'هغه سړي زه بېرته د عبادتځای د بهرنۍ حوېلۍ ختیځې دروازې ته بوتلم، خو هغه تړل شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_1.mp3', '', 1761754199, 1761754199),
(37762, 'Ezekiel 44:2', 'Ezekiel', 44, 2, 'څښتن ماته وویل: «دا دروازه به تړلې پاتې وي او هېڅکله به نه خلاصیږي. هېڅوک نه شي کولای چې په هغې باندې ننوځي، ځکه چې زه د اسراییلو څښتن تعالی په هغې باندې ننوتی یم. په دې خاطر هغه باید تړلې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_2.mp3', '', 1761754199, 1761754199),
(37763, 'Ezekiel 44:3', 'Ezekiel', 44, 3, 'یوازې د اسراییلو د هېواد مشر کولای شي چې هلته دننه لاړ شي او زما په حضور کې سپېڅلي خواړه وخوري. هغه باید د دهلېز د دنننۍ دروازې له لارې ننوځي او په همدې لاره باید دباندې ووځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_3.mp3', '', 1761754199, 1761754199),
(37764, 'Ezekiel 44:4', 'Ezekiel', 44, 4, 'بیا هغه سړي زه د شمالي دروازې له لارې د څښتن کور مخې ته بوتلم. څنګه چې مې وکتل، نو ما ولیدل چې کور د څښتن د جلال نه ډک شوی ؤ. زه په ځمکه باندې پړمخې پرېوتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_4.mp3', '', 1761754199, 1761754199),
(37765, 'Ezekiel 44:5', 'Ezekiel', 44, 5, 'څښتن ماته وویل: «ای فاني انسانه، څه چې وینې او اورې ورته پام کوه. زه تاته د څښتن د کور ټول قوانین وایم. دا په غور سره په یاد ساته چې کوم خلک اجازه لري د څښتن کور ته لاړ شي او راشي او کوم خلک اجازه نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_5.mp3', '', 1761754199, 1761754199),
(37766, 'Ezekiel 44:6', 'Ezekiel', 44, 6, 'د اسراییلو سرکښو خلکو ته ووایه چې زه څښتن تعالی داسې وایم: ‹تاسو دا ټول د کرکې وړ کارونه نور بس کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_6.mp3', '', 1761754199, 1761754199),
(37767, 'Ezekiel 44:7', 'Ezekiel', 44, 7, 'تاسو زما د عبادتځای سپکاوی کوئ، ځکه کله چې ماته د قربانیو وازګه او وینه وړاندې کوئ، په دې وخت کې پردیو ناسنته او هغو خلکو ته چې زما نافرماني کوي، اجازه ورکوئ چې زما کور ته ننوځي. نو تاسو په دې کارونو سره چې د کرکې وړ دي، زما لوظ ماتوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_7.mp3', '', 1761754199, 1761754199),
(37768, 'Ezekiel 44:8', 'Ezekiel', 44, 8, 'تاسو د دې په ځای چې زما په عبادتځای کې سپېڅلي مراسم سرته ورسوئ، نورو پرديو خلکو ته مو دا مسوولیت ورسپارلی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_8.mp3', '', 1761754199, 1761754199),
(37769, 'Ezekiel 44:9', 'Ezekiel', 44, 9, 'زه څښتن تعالی داسې وایم: ‹هرڅوک چې د اسراییلو د خلکو په منځ کې زما د عبادت کولو وړ نه وي، یعنې پردي خلک، هغه سړي چې ناسنته وي او یا زما نافرماني کوي، نه شي کولای زما عبادتځای ته ننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_9.mp3', '', 1761754199, 1761754199),
(37770, 'Ezekiel 44:10', 'Ezekiel', 44, 10, 'خو زه هغو لاویانو ته سزا ورکوم چې د اسراییلو د نورو خلکو سره یوځای یې زه پریښی یم او د بتانو عبادت یې کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_10.mp3', '', 1761754199, 1761754199),
(37771, 'Ezekiel 44:11', 'Ezekiel', 44, 11, 'هغوی کولای شي زما د عبادتځای د دروازو ساتنه وکړي او د هغه کارونه سرته ورسوي. هغوی دې هغه حیوانات چې خلک یې د سوځېدونکو نذرانو او قربانیو په توګه وړاندې کوي، حلال کړي او د خلکو په خدمت کې حاضر وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_11.mp3', '', 1761754199, 1761754199),
(37772, 'Ezekiel 44:12', 'Ezekiel', 44, 12, 'خو په دې خاطر چې هغوی د اسراییلو خلک د بتانو عبادت کولو ته وهڅول او په دې ډول یې هغوی د ګناه خواته بوتلل، نو ما څښتن تعالی قسم خوړلی دی چې هغوی ته به خامخا سزا ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_12.mp3', '', 1761754199, 1761754199),
(37773, 'Ezekiel 44:13', 'Ezekiel', 44, 13, 'هغوی به نور د کاهنانو په توګه زما خدمت نه کوي او نه به هغو شیانو ته ورنژدې کیږي چې ماته سپېڅلي دي او نه به ډېر سپېڅلي ځای ته ورننوځي. هغوی به د کرکې وړ هغو کارونو له امله چې کړي یې دي، وشرمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_13.mp3', '', 1761754199, 1761754199),
(37774, 'Ezekiel 44:14', 'Ezekiel', 44, 14, 'خو بیا به هم هغوی زما د کور د ساتلو او د بېلابېلو خدمتونو دپاره وټاکم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_14.mp3', '', 1761754199, 1761754199),
(37775, 'Ezekiel 44:15', 'Ezekiel', 44, 15, 'څښتن تعالی داسې وویل: «کله چې نورو اسراییلیانو زه پرېښودم او بې‌لارې شول، بیاهم د لاوي د قبیلې هغو کاهنانو چې د صادوق اولاده ده، په وفادارۍ سره زما په عبادتځای کې زما خدمت کاوه. نو هغوی هغه خلک دي چې زما خدمت به وکړي، زما حضور ته به راشي او ماته به د قربانیو وازګه او وینه وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_15.mp3', '', 1761754199, 1761754199),
(37776, 'Ezekiel 44:16', 'Ezekiel', 44, 16, 'یوازې هغوی به زما عبادتځای ته ننوځي، زما د قربانۍ په ځای کې به خدمت کوي او په عبادتځای کې به مراسم سرته رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_16.mp3', '', 1761754199, 1761754199),
(37777, 'Ezekiel 44:17', 'Ezekiel', 44, 17, 'کله چې هغوی د عبادتځای د دنننۍ حوېلۍ په لاره ننوځي، باید د کتان کالي واغوندي. کله چې هغوی د دنننۍ حوېلۍ په دروازو یا عبادتځای کې کار کوي، باید هغه کالي وانه غوندي چې د وړیو څخه جوړ شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_17.mp3', '', 1761754199, 1761754199),
(37778, 'Ezekiel 44:18', 'Ezekiel', 44, 18, 'د دې دپاره چې د هغوی بدن خولې نه شي، نو باید د کتان لونګۍ په سر کړي او نېکرونه واغوندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_18.mp3', '', 1761754199, 1761754199),
(37779, 'Ezekiel 44:19', 'Ezekiel', 44, 19, 'مخکې له دې چې هغوی باندینۍ حوېلۍ ته چې خلک په کې دي لاړ شي، باید خپل هغه کالي چې په عبادتځای کې یې د کار په وخت کې اغوندي، وباسي او په سپېڅلو کوټو کې دې پرېږدي. هغوی باید نور کالي واغوندي، ترڅو د هغوی سپېڅلي کالي خلکو ته زیان ونه رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_19.mp3', '', 1761754199, 1761754199),
(37780, 'Ezekiel 44:20', 'Ezekiel', 44, 20, 'کاهنان باید د خپلو سرونو ویښتان ونه خرایي او نه یې اوږده پرېږدي. هغوی باید خپل ویښتان په مناسبه اندازه وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_20.mp3', '', 1761754199, 1761754199),
(37781, 'Ezekiel 44:21', 'Ezekiel', 44, 21, 'کاهنان باید دنننۍ حوېلۍ ته د ننوتلو نه مخکې شراب ونه څښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_21.mp3', '', 1761754199, 1761754199),
(37782, 'Ezekiel 44:22', 'Ezekiel', 44, 22, 'هېڅ یو کاهن باید د کونډې یا د طلاقې شوې ښځې سره واده ونه کړي، هغه باید د اسراییلو د قوم نه د یوې پېغلې انجلۍ سره یا د بل کاهن د کونډې سره واده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_22.mp3', '', 1761754199, 1761754199),
(37783, 'Ezekiel 44:23', 'Ezekiel', 44, 23, 'کاهنان باید زما قوم ته د سپېڅلي او عادي شیانو تر منځ توپیر ورزده کړي او پاکو او ناپاکو شیانو ترمنځ فرق وروښایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_23.mp3', '', 1761754199, 1761754199),
(37784, 'Ezekiel 44:24', 'Ezekiel', 44, 24, 'کله چې یوه حقوقي دعوه رامنځته کیږي، نو کاهنان باید د هغې دعوې په هکله زما د حکمونو له مخې پرېکړه وکړي. هغوی باید زما اخترونه زما د قوانینو او مقرراتو له مخې ونیسي او باید زما د سبت ورځ سپېڅلې وګڼي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_24.mp3', '', 1761754199, 1761754199),
(37785, 'Ezekiel 44:25', 'Ezekiel', 44, 25, 'کاهنان باید مړو ته ورنژدې نه شي او په دې باندې خپل ځانونه ناپاکه نه کړي، خو په هغه حالت کې چې هغه یې مور او پلار وي یا د هغه زوی او لور وي یا یې ورور وي یا یې ناواده شوې خور وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_25.mp3', '', 1761754199, 1761754199),
(37786, 'Ezekiel 44:26', 'Ezekiel', 44, 26, 'کله چې هغه بېرته پاک شو، نو باید اووه ورځې صبر وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_26.mp3', '', 1761754199, 1761754199),
(37787, 'Ezekiel 44:27', 'Ezekiel', 44, 27, 'او بیا دې د عبادتځای دنننۍ حوېلۍ او سپېڅلي ځای ته لاړ شي چې د کاهن په توګه خدمت وکړي. خو د دې نه مخکې باید د خپل ځان دپاره د ګناه نذرانه وړاندې کړي. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_27.mp3', '', 1761754199, 1761754199),
(37788, 'Ezekiel 44:28', 'Ezekiel', 44, 28, 'کاهنتوب هغه میراث دی چې ما کاهنانو ته د اسراییلو په قوم کې ورکړی دی چې د یو نسل نه بل نسل ته به ولېږدول شي. هغوی باید په اسراییلو کې خپل جایداد ونه لري، ځکه چې زه د هغوی ملکیت او شتمني یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_28.mp3', '', 1761754199, 1761754199),
(37789, 'Ezekiel 44:29', 'Ezekiel', 44, 29, 'کاهنان به د غلو دانو نذرانې، د ګناه نذرانې او د تاوان نذرانې د خپل خوراک په توګه وکاروي او په اسراییلو کې چې هر څه ماته وقف کیږي، هغه به هغوی اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_29.mp3', '', 1761754199, 1761754199),
(37790, 'Ezekiel 44:30', 'Ezekiel', 44, 30, 'د لومړني فصل ډېر ښه حاصلات او د لومړنۍ برخې هرڅه چې ماته وړاندې کیږي، هغه به د کاهنانو وي. تاسو باید د خپلو اوړو اولنۍ پېړه کاهنانو ته ورکړئ، نو د هغوی په کورونو باندې به زما برکتونه نازل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_30.mp3', '', 1761754199, 1761754199),
(37791, 'Ezekiel 44:31', 'Ezekiel', 44, 31, 'کاهنان باید هغه مرغۍ یا حیوان چې په خپل مرګ مړ شوی وي او یا کوم وحشي حیوان وژلی وي، ونه خوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel44_verse_31.mp3', '', 1761754199, 1761754199),
(37792, 'Nehemiah 12:8', 'Nehemiah', 12, 8, 'لاویان: دې لاویانو د شکرګزارۍ د سندرو د ویلو مشري کوله: یشوع، بنوي، قدمي ییل، شربیا، یهودا او متنیا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_8.mp3', '', 1761754199, 1761754199),
(37793, 'Nehemiah 12:9', 'Nehemiah', 12, 9, 'بقبقیا او عني د خپلو ملګرو لاویانو سره هغې پورته یادې شوې ډلې ته مخامخ ودرېدل او د هغوی په ځواب کې یې سندرې ویلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_9.mp3', '', 1761754199, 1761754199),
(37794, 'Nehemiah 12:10', 'Nehemiah', 12, 10, 'یشوع د یویاقیم پلار، د الیاشیب نیکه او د یویاداع غور نیکه ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_10.mp3', '', 1761754199, 1761754199),
