(37796, 'Nehemiah 12:22', 'Nehemiah', 12, 22, 'د لاویانو او کاهنانو د کورنیو نومونه د دغو مشرانو کاهنانو یعنې الیاشیب، یویاداع، یوحانان او یدوع په زمانه کې ثبت شوي وو. د دې نومونو ثبتول د فارس د پاچا داریوش په دوران کې پای ته ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_22.mp3', '', 1761754199, 1761754199),
(37797, 'Nehemiah 12:23', 'Nehemiah', 12, 23, 'د لاویانو د مشرانو د کورنیو نومونه یوازې د الیاشیب د لمسي یوحانان تر زمانې پورې په رسمي توګه د تاریخ په کتاب کې ولیکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_23.mp3', '', 1761754199, 1761754199),
(37798, 'Nehemiah 12:24', 'Nehemiah', 12, 24, 'د حشبیا، شربیا او د قدمي ییل زوی یشوع د لاویانو مشران وو. د هغوی تر لارښوونو لاندې، لاویان په څو ډلو کې تنظیم شوي وو. د خدای د خدمتګار داود پاچا د لارښوونو سره سم دوه، دوه ډلې یو بل ته مخامخ ودرېدلې چې د خدای ثنا ووایي او شکرګزاري وکړي. د سندرو په ویلو سره یوې ډلې بلې ډلې ته ځواب ورکاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_24.mp3', '', 1761754199, 1761754199),
(37799, 'Nehemiah 12:25', 'Nehemiah', 12, 25, 'د خدای د کور هغه ساتونکي چې د دروازو تر څنګه د ګودامونو د ساتلو مسوولیت یې په غاړه ؤ، دا دي: متنیا، بقبقیا، عوبدیا، مشلام، طلمون او عقوب.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_25.mp3', '', 1761754199, 1761754199),
(37800, 'Nehemiah 12:26', 'Nehemiah', 12, 26, 'دا هغه خلک وو چې د یشوع د زوی او د یهوصادق د لمسي یویاقیم او د نحمیا والي او د شریعت د عالم او کاهن عزرا په زمانه کې یې ژوند کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_26.mp3', '', 1761754199, 1761754199),
(37801, 'Nehemiah 12:27', 'Nehemiah', 12, 27, 'کله چې د اورشلیم د ښار دېوال وقف کېده، لاویان د خپلو ټولو ځایونو څخه اورشلیم ته راوستل شول، ترڅو هغوی د شکرګزارۍ په سندرو او د شرنګېدونکو زنګونو، چنګونو او ربابونو په غږولو سره د وقف کېدلو په جشن کې ګډون وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_27.mp3', '', 1761754199, 1761754199),
(37802, 'Nehemiah 12:30', 'Nehemiah', 12, 30, 'کاهنانو او لاویانو لومړی د خپلو ځانونو دپاره او بیا د قوم، دروازو او د ښار د دېوال د پاکولو مذهبي مراسم تر سره کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_30.mp3', '', 1761754199, 1761754199),
(37803, 'Nehemiah 12:31', 'Nehemiah', 12, 31, 'ما د یهودا مشران د دېوال په سر باندې سره راټول کړل او د سندرغاړو دوه لویې ډلې مې وټاکلې چې د ښار شاوخوا وګرځي او د خدای د شکرګزارۍ سندرې ووایي. لومړنۍ ډله د دېوال په سر باندې جنوب خواته د خزلو د دروازې په لور لاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_31.mp3', '', 1761754199, 1761754199),
(37804, 'Nehemiah 12:32', 'Nehemiah', 12, 32, 'هوشعیا د سندرغاړو شاته روان ؤ او د یهودا د مشرانو څخه نیمایي یې په هغه پسې روان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_32.mp3', '', 1761754199, 1761754199),
(37805, 'Nehemiah 12:36', 'Nehemiah', 12, 36, 'ورپسې د زکریا خپلوان یعنې شمعیه، عزرییل، مللای، جللای، ماعای، نتنییل، یهودا او حناني وو. دوی د موسیقۍ هغه الې غږولې چې د خدای خدمتګار داود پورې یې اړه لرله. د شریعت عالم عزرا د دې ډلې لارښوونه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_36.mp3', '', 1761754199, 1761754199),
(37806, 'Nehemiah 12:37', 'Nehemiah', 12, 37, 'کله چې هغوی د چینې دروازې ته ورسېدل، په هغو زینو باندې چې د داود تر ښاره پورې رسېدلې وې، وختل او د داود له ماڼۍ څخه تېر شول او بېرته د اوبو د دروازې دېوال ته چې د ښار په ختیځه خوا کې ؤ، وروګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_37.mp3', '', 1761754199, 1761754199),
(37807, 'Nehemiah 12:38', 'Nehemiah', 12, 38, 'د شکرګزارۍ کولو بله ډله د دېوال په سر باندې شمال خواته لاړه او زه د نیمایي خلکو سره هغوی پسې روان وم. مونږ د تنورونو د برج څخه تېر شولو او پلن دېوال ته ورسېدلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_38.mp3', '', 1761754199, 1761754199),
(37808, 'Nehemiah 12:39', 'Nehemiah', 12, 39, 'او له هغه ځای څخه روان شولو او د افرایم له دروازې، یشانه دروازې، د ماهي دروازې، د حنن ییل له برج او د سلو له برجه تېر شولو او د پسونو دروازې ته ورسېدلو. په پای کې مونږ د خدای د کور دروازې ته نژدې ودرېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_39.mp3', '', 1761754199, 1761754199),
(37809, 'Nehemiah 12:40', 'Nehemiah', 12, 40, 'نو دواړه ډلې چې د خدای شکرګزاري یې کوله د خدای په کور کې په خپلو ټاکلو ځایونو کې ودرېدلې. برسېره پر هغو نیمو مشرانو چې زما سره وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_40.mp3', '', 1761754199, 1761754199),
(37810, 'Nehemiah 12:41', 'Nehemiah', 12, 41, 'زما په ډله کې دا لاندې کاهنان چې سرني ورسره وو، هم شریک وو: الیاقیم، معسیا، منیامین، میکایا، الیوعینای، زکریا او حننیا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah12_verse_41.mp3', '', 1761754199, 1761754199);